"use client";

import dynamic from "next/dynamic";
import { createElement, type ComponentType } from "react";
import { I18nProvider, useI18n } from "@/contexts/I18nContext";
import { ToastProvider } from "@/contexts/ToastContext";
import { loadRemotePluginModule } from "@/lib/pluginBundleLoader";
import { PORTAL_PAGES } from "@/lib/portalPluginRegistry";

/**
 * The client half of /portal/<slug>[/…]: renders the plugin's portal component.
 *
 * WHICH CODE: a plugin present at build time is compiled in (src/lib/portalPluginRegistry.ts, generated by
 * scripts/generate-portal-plugin-registry.js); one installed at runtime is not, and its pre-compiled
 * dist/portal.bundle.js is loaded instead (GET /api/v1/plugins/<slug>/bundle?type=portal — active +
 * browser:script, resolved by the PORTAL slug). The component receives { slug, path } — path being the
 * segments after the slug (/portal/<slug>/a/b → ["a", "b"], [] at the portal root) — and reads the rest of
 * the URL (query string, hash) itself.
 *
 * WHAT IT GETS: the bare /portal layout (no theme chrome, no admin shell), ModalProvider (root layout),
 * I18nProvider and ToastProvider (here), and its compiled Tailwind classes — dist/portal.bundle.css from
 * the anonymous bundle/css route, since a runtime-installed plugin's classes are in no host stylesheet.
 */

function PortalLoading() {
    return (
        <div className="min-h-screen flex items-center justify-center" aria-busy="true">
            <div className="w-8 h-8 border-4 border-gray-300 border-t-transparent rounded-full animate-spin" />
        </div>
    );
}

function PortalUnavailable() {
    const { t } = useI18n();
    return (
        <div className="min-h-screen flex items-center justify-center p-6">
            <p className="max-w-md text-center text-gray-600">{t("portal.unavailable")}</p>
        </div>
    );
}

// One component per portal slug for the life of the page — created once, outside render, so React never
// sees a new component type (and remounts the portal) on a re-render.
type PortalProps = { slug: string; path: string[] };

const PORTAL_COMPONENTS = new Map<string, ComponentType<PortalProps>>();

function portalComponent(slug: string): ComponentType<PortalProps> {
    let Page = PORTAL_COMPONENTS.get(slug);
    if (!Page) {
        // Own keys only: a slug such as "constructor" must not find Object.prototype's.
        const staticLoader = Object.prototype.hasOwnProperty.call(PORTAL_PAGES, slug) ? PORTAL_PAGES[slug] : undefined;
        const load = staticLoader
            ? () => staticLoader().catch(() => ({ default: PortalUnavailable }))
            : () => loadRemotePluginModule(slug, "portal", PortalUnavailable);
        Page = dynamic(load, { loading: () => <PortalLoading />, ssr: false });
        PORTAL_COMPONENTS.set(slug, Page);
    }
    return Page;
}

export default function PluginPortal({ slug, path }: PortalProps) {
    const cssUrl = `/api/v1/plugins/${encodeURIComponent(slug)}/bundle/css?type=portal`;

    return (
        <I18nProvider>
            <ToastProvider>
                <link rel="stylesheet" href={cssUrl} />
                <PortalPage slug={slug} path={path} />
            </ToastProvider>
        </I18nProvider>
    );
}

function PortalPage({ slug, path }: PortalProps) {
    return createElement(portalComponent(slug), { slug, path });
}
